def is_valid(coloring):
    N = len(coloring)
    # The forbidden sequence is B-R-B-R
    forbidden = ['B', 'R', 'B', 'R']

    if N < 4:
        return True

    for i in range(N):
        # Check the sequence starting at i (circularly)
        sequence = [coloring[(i + j) % N] for j in range(4)]
        if sequence == forbidden:
            return False
    return True

# Check all 2^5 = 32 colorings for N=5
N5_valid_colorings = []
import itertools
colors_set = ['R', 'B']
for coloring_tuple in itertools.product(colors_set, repeat=5):
    if is_valid(list(coloring_tuple)):
        N5_valid_colorings.append(coloring_tuple)

print(f"Found {len(N5_valid_colorings)} valid colorings for N=5.")
